+package com.example;
+
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+import org.springframework.stereotype.Component;
+
+@Component
+public class ContactMessageStore {
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public synchronized List<ContactMessage> getMessages() {
+        return Collections.unmodifiableList(new ArrayList<>(messages));
+    }
+}
diff --git a/src/main/java/com/example/ContactView.java b/src/main/java/com/example/ContactView.java
new file mode 100644
index 0000000..7ef33f5
--- /dev/null
+++ b/src/main/java/com/example/ContactView.java
@@ -0,0 +1,144 @@
+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final ContactMessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>();
+
+    private boolean changed;
+
+    public ContactView(ContactMessageStore messageStore) {
+        this.messageStore = messageStore;
+        email.setManualValidation(true);
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message, send);
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> fieldEdited());
+        email.addValueChangeListener(event -> fieldEdited());
+        phone.addValueChangeListener(event -> fieldEdited());
+        message.addValueChangeListener(event -> fieldEdited());
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        refreshMessages();
+
+        add(form, messages);
+    }
+
+    private void fieldEdited() {
+        changed = true;
+        send.setEnabled(true);
+    }
+
+    private void sendMessage() {
+        clearValidationErrors();
+
+        boolean valid = true;
+        if (name.getValue().isBlank()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty()
+                && email.getDefaultValidator().apply(emailValue, null).isError()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        }
+        if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        refreshMessages();
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        changed = false;
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void clearValidationErrors() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private void refreshMessages() {
+        messages.setItems(messageStore.getMessages());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!changed || allFieldsEmpty()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(new Span("You have unsent changes. Leave this page?"), keepEditing, discard);
+        dialog.open();
+    }
+
+    private boolean allFieldsEmpty() {
+        return name.getValue().isEmpty()
+                && email.getValue().isEmpty()
+                && phone.getValue().isEmpty()
+                && message.getValue().isEmpty();
+    }
+}
